WITH account_totals AS (SELECT account_id, COUNT(*) AS total_count, MIN(amount) AS min_amount FROM transactions WHERE txn_type IN ('CREDIT', 'REFUND', 'DEBIT') GROUP BY account_id) SELECT accounts.balance, accounts.account_type, account_totals.total_count, account_totals.min_amount FROM accounts JOIN account_totals ON accounts.id = account_totals.account_id WHERE account_totals.total_count > 5 ORDER BY balance DESC;
